def transform_v2(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    pairs=set()
    for r in range(h):
      for c in range(w):
       color=grid[r][c]
       if color==bg: continue
       for dr,dc in [(1,1),(1,-1)]:
        rr,cc=r+dr,c+dc
        if 0<=rr<h and 0<=cc<w and grid[rr][cc]==color:
         # A full 2x2 multicolor block is not a line seed: require its other diagonal corners to be background.
         a=(r,c+dc); b=(rr,c)
         if grid[a[0]][a[1]] != bg or grid[b[0]][b[1]] != bg:
          continue
         pairs.add((color,r,c,rr,cc,dr,dc))
    for color,r1,c1,r2,c2,dr,dc in pairs:
      for r,c,vr,vc in ((r1,c1,-dr,-dc),(r2,c2,dr,dc)):
       rr,cc=r+vr,c+vc
       while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
        out[rr][cc]=color
        rr+=vr;cc+=vc
    return out
